const templateID = this.getValue(`dialog_print_template.template_id`);
const salesInvoiceID = this.getValue("sales_invoice_id");

window.open(
`/sucode/openpage/${templateID}?sales_invoice_id=${salesInvoiceID}&name=Sales+Invoice`
);

this.setData({[`dialog_print_template.template_id`]: '', [`dialog_print_template.print_template_id`]: ''})

this.closeDialog("dialog_print_template");

(async () => {
  const plantId = this.getVarSystem("deptIds").split(",")[0];
  this.setData({ sales_invoice_id: arguments[0].row.id });

  const resTemplateAccess = await db
    .collection("print_template_access")
    .filter([
      {
        type: "branch",
        operator: "all",
        children: [
          {
            prop: "plant_id",
            operator: "in",
            value: plantId,
          },
          {
            prop: "doc_type",
            operator: "equal",
            value: "sales_invoice",
          },
        ],
      },
    ])
    .get();

  if (!resTemplateAccess || resTemplateAccess.data.length === 0) {
    this.message.error("No print template found.");
    return;
  } else if (resTemplateAccess && resTemplateAccess.data.length === 1) {
    const templateID = resTemplateAccess.data[0].print_template_id;

    window.open(
      `/sucode/openpage/${templateID}?sales_invoice.id=${arguments[0].row.id}&name=Sales+Invoice`
    );
  } else if (resTemplateAccess && resTemplateAccess.data.length > 1) {
    await this.openDialog("dialog_print_template");
    setTimeout(() => {
      this.setOptionData(
        `dialog_print_template.print_template_id`,
        resTemplateAccess.data
      );
    }, 50);
  }
})();

(async () => {
  try {
    let dialogFields = this.getValue("dialog_update_field");
    const salesInvoiceId = JSON.parse(this.getValue("sales_invoice_id"));

    dialogFields = Object.entries(dialogFields).reduce((acc, [key, value]) => {
      if (value !== "" && value !== null && value !== undefined) {
        acc[key] = value;
      }
      return acc;
    }, {});

    console.log("dialogFields", dialogFields);
    console.log("salesInvoiceId", salesInvoiceId);

    await Promise.all(
      salesInvoiceId.map(async (id) =>
        db.collection("sales_invoice").doc(id).update(dialogFields)
      )
    );

    this.$message.success("Update successfully");
    await this.closeDialog("dialog_update_field");
    this.refresh();
  } catch (error) {
    this.$message.error(error);
  }
})();

(async () => {
  try {
    const unCompletedListID = "custom_lwxe7tfp";
