(async () => {
  try {
    const unCompletedListID = "custom_lwxe7tfp";
    const allListID = "custom_wfwjnk9q";
    const tabUncompletedElement = document.getElementById("tab-tab_unposted");
    const organizationID = this.getVarGlobal("firstLvDeptId");
    this.showLoading("Post Sales Invoice...");

    const activeTab = tabUncompletedElement?.classList.contains("is-active")
      ? "Uncompleted"
      : "All";

    let selectedRecords;

    selectedRecords = this.getComponent(
      activeTab === "Uncompleted" ? unCompletedListID : allListID,
    )?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);
    selectedRecords = selectedRecords.filter(
      (item) => item.si_status === "Completed" && item.posted_status !== 'Pending Post',
    );

    if (selectedRecords && selectedRecords.length > 0) {
      const resAI = await db
        .collection("accounting_integration")
        .where({ organization_id: organizationID })
        .get();
      if (resAI && resAI.data.length > 0) {
        const accIntegrationType = resAI.data[0].acc_integration_type;

        if (accIntegrationType !== "No Accounting Integration") {
          await this.runWorkflow(
            "2029464545187823617",
            {
              si_ids: selectedRecords.map((item) => item.id),
              acc_integration_type: accIntegrationType,
            },
            async (res) => {
              console.log("res", res.data);
              this.$message.success("Sales Invoice posted successfully");
              this.hideLoading();
            },
            async (err) => {
              console.error(err);
              // this.$message.error("Posting Sales Invoice failed");
              this.hideLoading();
            },
          );
        }
      }

      await this.getComponent(
        activeTab === "Uncompleted" ? unCompletedListID : allListID,
      )?.$refs.crud.clearSelection();
      this.refresh();
      this.hideLoading();
    } else {
      this.$message.error("Please select at least one record.");
    }
  } catch (error) {
    console.error(error);
  }
})();

